import re, json, os

ids = {
 'A': '1_zgKRBrT0Y', 'B': 't_jHrUE5IOk', 'C': 'NUsoVlDFqZg', 'D': 'wnJ6LuUFpMo',
 'E': 'RBumgq5yVrA', 'F': '-UV0QGLmYys', 'G': 'JGwWNGJdvx8', 'H': 'TapXs54Ah3E',
 'I': 'QFs3PIZb3js', 'J': 'VqEbCxg2bNI'}

specs = {}
for k, vid in ids.items():
    html = open(f'pages/{vid}.html', encoding='utf-8', errors='ignore').read()
    m = re.search(r'"playerStoryboardSpecRenderer":\{"spec":"(.*?)"\}', html)
    spec = m.group(1) if m else None
    # unescape
    if spec:
        spec = spec.encode().decode('unicode_escape')
    specs[k] = (vid, spec)
    print(k, vid, 'spec found' if spec else 'NO SPEC', (spec[:80] if spec else ''))

json.dump(specs, open('storyboard_specs.json','w'))
